def compute_metric(orders, refunds):
    seen = {}
    for row in refunds:
        rid = row.get('refund_id')
        if rid is not None:
            seen[rid] = 1
    unique_refund_events = len(seen)
    data = {'unique_refund_events': unique_refund_events}
    evidence = {'refund_rows': len(refunds), 'distinct_refund_ids': unique_refund_events}
    return {'metric': unique_refund_events, 'data': data, 'evidence': evidence}
